1	import { test, beforeEach, afterEach } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { rm, mkdir, appendFile } from 'node:fs/promises';
4	import path from 'node:path';
5	import { tmpdir } from 'node:os';
6	import { createBus } from '../src/index.js';
7	
8	let dirs = [];
9	
10	async function freshDir() {
11	  const dir = path.join(tmpdir(), `replay-bus-${Math.random().toString(36).slice(2)}`);
12	  await mkdir(dir, { recursive: true });
13	  dirs.push(dir);
14	  return dir;
15	}
16	
17	beforeEach(() => {});
18	
19	afterEach(async () => {
20	  const all = dirs;
21	  dirs = [];
22	  await Promise.all(all.map((d) => rm(d, { recursive: true, force: true })));
23	});
24	
25	test('createBus returns bus synchronously and rejects bad path with TypeError', () => {
26	  assert.throws(() => createBus(), TypeError);
27	  assert.throws(() => createBus({}), TypeError);
28	  assert.throws(() => createBus({ path: undefined }), TypeError);
29	  assert.throws(() => createBus({ path: '' }), TypeError);
30	  assert.throws(() => createBus({ path: 123 }), TypeError);
31	  // Synchronous return, not a Promise.
32	  const dir = '/tmp/replay-bus-sync-check';
33	  const bus = createBus({ path: dir });
34	  assert.equal(typeof bus.publish, 'function');
35	  dirs.push(dir);
36	  return bus.close();
37	});
38	
39	test('empty bus: stats zeros, replay empty, beyond-end empty', async () => {
40	  const dir = await freshDir();
41	  const bus = createBus({ path: dir });
42	  assert.deepEqual(bus.stats(), { seq: 0, bytes: 0, published: 0, replayed: 0 });
43	  assert.deepEqual(await bus.replay(), []);
44	  assert.deepEqual(await bus.replay(0), []);
45	  assert.deepEqual(await bus.replay(5), []);
46	  assert.equal(bus.stats().replayed, 0);
47	  await bus.close();
48	});
49	
50	test('publish: seq from 1 continuous, ids unique, bytes are compact UTF-8', async () => {
51	  const dir = await freshDir();
52	  const bus = createBus({ path: dir });
53	  const r1 = { a: 1 };
54	  const r2 = { msg: '你好', nested: { x: [1, 2, 3] } };
55	  const a = await bus.publish(r1);
56	  const b = await bus.publish(r2);
57	  assert.deepEqual(a, { id: a.id, seq: 1 });
58	  assert.equal(b.seq, 2);
59	  assert.equal(typeof a.id, 'string');
60	  assert.notEqual(a.id, b.id);
61	  const expected =
62	    Buffer.byteLength(JSON.stringify(r1), 'utf8') +
63	    Buffer.byteLength(JSON.stringify(r2), 'utf8');
64	  assert.deepEqual(bus.stats(), {
65	    seq: 2,
66	    bytes: expected,
67	    published: 2,
68	    replayed: 0,
69	  });
70	  await bus.close();
71	});
72	
73	test('replay is inclusive of start, ascending, record as-is', async () => {
74	  const dir = await freshDir();
75	  const bus = createBus({ path: dir });
76	  const records = [{ v: 1 }, { v: 2, x: '你好' }, { v: 3 }];
77	  const acks = [];
78	  for (const r of records) acks.push(await bus.publish(r));
79	
80	  let got = await bus.replay(0);
81	  assert.deepEqual(got.map((m) => m.seq), [1, 2, 3]);
82	  assert.deepEqual(got.map((m) => m.record), records);
83	  assert.deepEqual(got.map((m) => m.id), acks.map((a) => a.id));
84	
85	  got = await bus.replay(2);
86	  assert.deepEqual(got.map((m) => m.seq), [2, 3]);
87	  assert.deepEqual(got[0].record, records[1]);
88	
89	  got = await bus.replay(3);
90	  assert.deepEqual(got.map((m) => m.seq), [3]);
91	
92	  got = await bus.replay(99);
93	  assert.deepEqual(got, []);
94	
95	  // Each replay counts the messages it returned; empty replays count nothing.
96	  assert.equal(bus.stats().replayed, 3 + 2 + 1);
97	  await bus.close();
98	});
99	
100	test('dedupKey: resend reuses first id/seq, no new message', async () => {
101	  const dir = await freshDir();
102	  const bus = createBus({ path: dir });
103	  const first = await bus.publish({ order: 'A', dedupKey: 'k1' });
104	  const again = await bus.publish({ order: 'A-different-body', dedupKey: 'k1' });
105	  assert.deepEqual(again, first);
106	  assert.equal(bus.stats().published, 1);
107	  assert.equal(bus.stats().seq, 1);
108	  const got = await bus.replay(0);
109	  assert.equal(got.length, 1);
110	  assert.deepEqual(got[0].record, { order: 'A', dedupKey: 'k1' });
111	  await bus.close();
112	});
113	
114	test('dedup serves an in-flight first publish and keys without dedupKey are distinct', async () => {
115	  const dir = await freshDir();
116	  const bus = createBus({ path: dir, fsync: true });
117	  const p1 = bus.publish({ order: 'A', dedupKey: 'k1' });
118	  const p2 = bus.publish({ order: 'A', dedupKey: 'k1' });
119	  const [a, b] = await Promise.all([p1, p2]);
120	  assert.deepEqual(a, b);
121	  assert.equal(bus.stats().published, 1);
122	
123	  const c = await bus.publish({ x: 1 });
124	  const d = await bus.publish({ x: 1 });
125	  assert.notEqual(c.id, d.id);
126	  assert.equal(c.seq, 2);
127	  assert.equal(d.seq, 3);
128	  await bus.close();
129	});
