131	test('concurrent publishes take seq in invocation order', async () => {
132	  const dir = await freshDir();
133	  const bus = createBus({ path: dir });
134	  const ps = [];
135	  for (let i = 0; i < 20; i++) {
136	    ps.push(bus.publish({ i }));
137	  }
138	  const acks = await Promise.all(ps);
139	  assert.deepEqual(
140	    acks.map((a) => a.seq),
141	    acks.map((_, i) => i + 1),
142	  );
143	  assert.equal(bus.stats().seq, 20);
144	  await bus.close();
145	});
