import { createBus } from './src/index.js';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';

const dir = mkdtempSync(path.join(tmpdir(), 'bus-sanity-'));
// empty bus: compact then reopen
let bus = createBus({ path: dir });
await bus.compact();
console.log('empty stats:', JSON.stringify(bus.stats()));
bus.advance('a', 5); // beyond end allowed
console.log('read beyond end:', JSON.stringify(bus.read('a')));
await bus.close();

bus = createBus({ path: dir });
console.log('after reopen stats:', JSON.stringify(bus.stats()), 'pos a =', bus.register('a'));
const ack = await bus.publish({ hello: 'world', dedupKey: 'x' });
console.log('publish after empty-compact reopen:', JSON.stringify(ack));
await bus.compact();
await bus.close();

bus = createBus({ path: dir });
console.log('replay:', JSON.stringify(await bus.replay(0)));
console.log('dup:', JSON.stringify(await bus.publish({ other: 1, dedupKey: 'x' })));
console.log('read a:', JSON.stringify(bus.read('a')));
await bus.close();
console.log('OK');
"

